"""
  Slightly improved insertion sort

  Complexity: O(n ** 2)

  """
def insertion_sort2(L: Any) -> object {
    for i in range(len(L)) {
        key = L[i];
        j = i - 1;
        while ((j > -1) and (L[j] > key)) {
            L[(j + 1)] = L[j];
            j -= 1;
        }
        L[(j + 1)] = key;
    }
    return L;
}

"""
    Finds the maximum length of a bucket in buckets (dict as returned by bucket_sort)

    Parameters
    ----------
    buckets : dict
        contains a map of ranks to list of cards

    Returns
    -------
    integer
        length of the longest bucket in buckets
    """
def max_bucket_len(buckets: Any) -> object {
    m = 1;
    for (k, v) in buckets.items() {
        m = max(m, len(v));
    }
    return m;
}

"""Quote a value if it isn't quoted yet.

    :param value: the string to quote
    :type value: Any
    :param tag: if this is a tag, then don't quote it, but make sure it has no
        spaces.
    :type tag: bool
    :returns: quoted value
    :rtype: str
    """
def format_value(value: Any, tag: Any = False) -> object {
    if tag {
        if not isinstance(value, str) {
            value = str(value);
        }
        return value.replace(' ', '-');
    }
    if isinstance(value, str) {
        if (value.startswith('"') and value.endswith('"')) {
            return value;
        }
    }
    return '"{}"'.format(value);
}

